import { useEffect, useState } from 'react';
import { Card } from '@/types/statistics';
import PeopleIcon from '@/components/icons/PeopleIcon';
import TwoUserIcon from '@/components/icons/TwoUsersIcon';
import UserRemoveIcon from '@/components/icons/UserRemoveIcon';
import UserMinusIcon from '@/components/icons/UserMinusIcon';
import StatisticsCards from '@/components/cards/StatisticsCards';
import { apiGet } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';

type EmployeeDashboard = {
    total_employees: number;
    total_part_time: number;
    total_full_time: number;
};

export default function StatisticsCardsComponent() {
    const [cards, setCards] = useState<Card[]>([]);

    useEffect(() => {
        const load = async () => {
            try {
                const res = await apiGet<{ data: EmployeeDashboard }>({
                    endpoint: endpoints.employee.dashboard,
                });
                const d = res.data.data;
                const other = Math.max(0, d.total_employees - d.total_full_time - d.total_part_time);
                setCards([
                    { text: 'إجمالي العاملين', icon: <PeopleIcon />, num: d.total_employees, percent: 0 },
                    { text: 'دوام كامل', icon: <TwoUserIcon />, num: d.total_full_time, percent: 0 },
                    { text: 'دوام جزئي', icon: <UserMinusIcon />, num: d.total_part_time, percent: 0 },
                    { text: 'عقود أخرى', icon: <UserRemoveIcon />, num: other, percent: 0 },
                ]);
            } catch {
                setCards([
                    { text: 'إجمالي العاملين', icon: <PeopleIcon />, num: 0, percent: 0 },
                    { text: 'دوام كامل', icon: <TwoUserIcon />, num: 0, percent: 0 },
                    { text: 'دوام جزئي', icon: <UserMinusIcon />, num: 0, percent: 0 },
                    { text: 'عقود أخرى', icon: <UserRemoveIcon />, num: 0, percent: 0 },
                ]);
            }
        };
        load();
    }, []);

    if (!cards.length) {
        return (
            <div className="grid grid-cols-[repeat(auto-fit,minmax(258px,1fr))] gap-6 justify-center sm:justify-between min-h-[120px]" />
        );
    }

    return <StatisticsCards cards={cards} />;
}
