import { PieChartComponent } from '@/components/charts/PieChart';
import UnderlineHeading from '@/components/heading/UnderlineHeading';
import { CustomSelect } from '@/components/dropDown/Dropdown';
import { useEffect, useState } from 'react';
import { ChartConfig } from '@/components/ui/chart';
import { apiGet } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import List from '@/features/car/components/statistics/List';

const SEG_KEYS = ['seg0', 'seg1', 'seg2', 'seg3', 'seg4'] as const;

export default function AverageSalaries() {
    const [selectedValue, setSelectedValue] = useState('');
    const [loading, setLoading] = useState(true);
    const [chartData, setChartData] = useState<{ days: string; visitors: number; fill: string }[]>([]);
    const [listText, setListText] = useState<string[]>([]);

    useEffect(() => {
        let cancelled = false;
        const load = async () => {
            setLoading(true);
            try {
                const now = new Date();
                const month = now.getMonth() + 1;
                const year = now.getFullYear();
                const first = await apiGet({
                    endpoint: endpoints.employee.salaryList,
                    queryParams: { page: 1, pageSize: 1, month, year },
                });
                const total: number = first.data.data.pagination?.total ?? 0;
                if (total === 0) {
                    if (!cancelled) {
                        setChartData([]);
                        setListText([]);
                    }
                    return;
                }
                const res = await apiGet({
                    endpoint: endpoints.employee.salaryList,
                    queryParams: { page: 1, pageSize: Math.min(total, 5000), month, year },
                });
                const rows = res.data.data.data as {
                    position: string;
                    total_salary: number;
                }[];
                const byPosition = new Map<string, { sum: number; n: number }>();
                for (const r of rows) {
                    const key = (r.position || 'غير محدد').trim() || 'غير محدد';
                    const prev = byPosition.get(key) ?? { sum: 0, n: 0 };
                    prev.sum += Number(r.total_salary) || 0;
                    prev.n += 1;
                    byPosition.set(key, prev);
                }
                const sorted = [...byPosition.entries()]
                    .map(([name, { sum, n }]) => ({ name, avg: n > 0 ? Math.round(sum / n) : 0, n }))
                    .sort((a, b) => b.n - a.n)
                    .slice(0, 5);
                const nextChart = sorted.map((row, i) => ({
                    days: row.name,
                    visitors: row.avg,
                    fill: `var(--color-${SEG_KEYS[i % SEG_KEYS.length]})`,
                }));
                const nextList = sorted.map((row) => `${row.name}: ${row.avg}`);
                if (!cancelled) {
                    setChartData(nextChart);
                    setListText(nextList);
                }
            } catch {
                if (!cancelled) {
                    setChartData([]);
                    setListText([]);
                }
            } finally {
                if (!cancelled) setLoading(false);
            }
        };
        load();
        return () => {
            cancelled = true;
        };
    }, []);

    const chartConfig = {
        visitors: { label: 'Visitors' },
        seg0: { label: '1', color: 'hsl(var(--chart-1))' },
        seg1: { label: '2', color: 'hsl(var(--chart-2))' },
        seg2: { label: '3', color: 'hsl(var(--chart-3))' },
        seg3: { label: '4', color: 'hsl(var(--chart-4))' },
        seg4: { label: '5', color: 'hsl(var(--chart-5))' },
    } satisfies ChartConfig;

    return (
        <div className="flex flex-col justify-between p-4 shadow-[0px_2px_12px_0px_#14142B14] rounded-[0.5rem]">
            <div className="flex flex-row justify-between mb-4">
                <UnderlineHeading text="متوسط الرواتب حسب المسمى" />
                <CustomSelect
                    options={[
                        { label: 'يومي', value: 'يومي' },
                        { label: 'أسبوعي ', value: 'أسبوعي ' },
                        { label: 'شهري', value: 'شهري' },
                        { label: 'سنوي', value: 'سنوي' },
                    ]}
                    value={selectedValue}
                    onValueChange={setSelectedValue}
                    placeholder="القائمة"
                    width="min-w-[101px]"
                />
            </div>
            <div className="flex flex-row items-center justify-between mb-8">
                {loading ? (
                    <p className="text-sm text-[#625E74] text-end w-full">جاري التحميل…</p>
                ) : chartData.length === 0 ? (
                    <p className="text-sm text-[#625E74] text-end w-full">لا توجد بيانات رواتب لهذا الشهر.</p>
                ) : (
                    <>
                        <List text={listText} />
                        <PieChartComponent chartData={chartData} chartConfig={chartConfig} />
                    </>
                )}
            </div>
        </div>
    );
}
